import json
out=json.load(open('batch_083_out.json'))
inp={p['key']:p for p in json.load(open('batch_083_in.json'))}
SB="https://renaissance.stonybrookmedicine.edu/neurosurgery/residency_program/current-residents"
def rec(key,ident,basis,res,outcome,detail,cur,dox,srcs,ns,agree=True,dis="",abns=False,yl=None,dest=None,ds=None):
    p=inp[key]
    out.append({"key":key,"name":p['name'],"program_id":p['program_id'],"identity":ident,"identity_basis":basis,
     "residency_stated":res,"outcome":outcome,"outcome_detail":detail,"year_left":yl,"destination_program":dest,"destination_start_year":ds,
     "current":cur,"agrees_with_db":agree,"disagreement":dis,"checks":{"google":"found","doximity":dox,"usnews":"deferred"},
     "abns_certified":abns,"sources":srcs,"searches_used":ns})
sbp="Stony Brook Medicine Program"
def sbres(s): return [{"institution":sbp,"specialty":"neurosurgery","start":s,"end":None}]
def dx(u,e): return {"url":u,"type":"doximity","evidence":e}
def sb(e): return {"url":SB,"type":"program_page","evidence":e}
